import java.io.*;import java.util.*;import org.jf.dexlib2.*;import org.jf.dexlib2.iface.*;import org.jf.dexlib2.iface.instruction.*;import org.jf.dexlib2.iface.reference.*;
/** Exercise native lifecycle entry paths while the folder chooser leaves cache fields uninitialized. */
public final class VerifyFolderFirstLifecycle {
 static String execute(Method method,boolean initialized){List<Instruction> code=new ArrayList<>();Map<Integer,Integer> positions=new HashMap<>();int at=0;for(Instruction i:method.getImplementation().getInstructions()){positions.put(at,code.size());code.add(i);at+=i.getCodeUnits();}Object[] regs=new Object[method.getImplementation().getRegisterCount()];Arrays.fill(regs,new Object());boolean result=false,superCalled=false,stopped=false;int pc=0;at=0;
  for(int steps=0;steps<100;steps++){Instruction i=code.get(pc);Opcode op=i.getOpcode();int next=at+i.getCodeUnits();
   if(op==Opcode.IGET_OBJECT){FieldReference f=(FieldReference)((ReferenceInstruction)i).getReference();regs[((OneRegisterInstruction)i).getRegisterA()]=(f.getName().equals("O")||!initialized)?null:new Object();}
   else if(op==Opcode.CONST_4||op==Opcode.CONST_16||op==Opcode.CONST)regs[((OneRegisterInstruction)i).getRegisterA()]=((NarrowLiteralInstruction)i).getNarrowLiteral();
   else if(op==Opcode.MOVE_RESULT)regs[((OneRegisterInstruction)i).getRegisterA()]=result?1:0;
   else if(op==Opcode.IF_EQZ||op==Opcode.IF_NEZ){Object r=regs[((OneRegisterInstruction)i).getRegisterA()];boolean truth=r!=null&&(!(r instanceof Number)||((Number)r).intValue()!=0);if(op==Opcode.IF_NEZ?truth:!truth)next=at+((OffsetInstruction)i).getCodeOffset();}
   else if(op==Opcode.RETURN_VOID){if(!superCalled)throw new AssertionError("Lifecycle omitted super");return "blocked";}
   else if(op==Opcode.RETURN){Object r=regs[((OneRegisterInstruction)i).getRegisterA()];if(method.getName().equals("onStartCommand")&&(!superCalled||!stopped||!Integer.valueOf(2).equals(r)))throw new AssertionError("Worker must stop without sticky restart");return "blocked";}
   else if(i instanceof ReferenceInstruction&&((ReferenceInstruction)i).getReference() instanceof MethodReference){MethodReference ref=(MethodReference)((ReferenceInstruction)i).getReference();if(op==Opcode.INVOKE_SUPER||op==Opcode.INVOKE_SUPER_RANGE)superCalled=true;else if(ref.getDefiningClass().equals("Le/e/a/CacheFolders;")&&(ref.getName().equals("page")||ref.getName().equals("workerReady")))result=initialized;else if(ref.getName().equals("stopSelf"))stopped=true;else if(ref.getName().equals("setTheme")||ref.getName().equals("getString")||ref.getDefiningClass().equals("Le/e/a/y0;")&&ref.getName().equals("a")||ref.getDefiningClass().equals("Ld/b/k/a;")&&ref.getName().equals("b")){if(!initialized)throw new AssertionError("Uninitialized cache fields used in "+method.getName());return "setup";}}
   else throw new AssertionError("Unexpected entry opcode "+op);
   Integer index=positions.get(next);if(index==null)throw new AssertionError("Bad entry branch");pc=index;at=next;
  }throw new AssertionError("Entry did not settle");
 }
 public static void main(String[] args)throws Exception{MultiDexContainer<? extends DexFile> zip=DexFileFactory.loadDexContainer(new File(args[0]),Opcodes.getDefault());Map<String,ClassDef> types=new HashMap<>();for(String n:zip.getDexEntryNames())for(ClassDef c:zip.getEntry(n).getDexFile().getClasses())types.put(c.getType(),c);int checks=0;for(String owner:new String[]{"Lcom/sauzask/nicoid/NicoidCacheManagerActivity;","Lcom/sauzask/nicoid/NicoidDownloadCache;","Lcom/sauzask/nicoid/NicoidActivity;"})for(Method m:types.get(owner).getMethods())if((owner.contains("Manager")&&Arrays.asList("onCreate","onPause","onCreateOptionsMenu").contains(m.getName()))||owner.contains("Download")&&m.getName().equals("onStartCommand")||owner.equals("Lcom/sauzask/nicoid/NicoidActivity;")&&m.getName().equals("onPostCreate")){if(!"blocked".equals(execute(m,false)))throw new AssertionError("Unselected folder reached setup");if(!"setup".equals(execute(m,true)))throw new AssertionError("Selected folder did not resume setup");checks+=2;}if(checks!=10)throw new AssertionError("Missing folder entry points");int routes=0;for(Method m:types.get("Lcom/sauzask/nicoid/NicoidTopActivity$b;").getMethods())if(m.getName().equals("onItemClick"))for(Instruction i:m.getImplementation().getInstructions())if(i instanceof ReferenceInstruction&&((ReferenceInstruction)i).getReference() instanceof MethodReference){MethodReference ref=(MethodReference)((ReferenceInstruction)i).getReference();if(ref.getName().equals("startActivity")){if(!ref.getDefiningClass().equals("Le/e/a/CacheFolders;"))throw new AssertionError("Drawer bypasses folder-first navigation");routes++;}}if(routes!=1)throw new AssertionError("Missing drawer route");System.out.println("Folder-first native lifecycle: 10 page/worker/menu/pause/post-create paths passed");}
}
